import{_ as r,K as d,a as i,c as n,ac as a,b as o,q as l}from"./chunks/framework.BSuaGltH.js";const x=JSON.parse('{"title":"易经：专题导读与学习地图","description":"从阴阳、八卦和六爻读法进入六十四卦经文、十翼与历代注解，配合本地图谱、术语表和可追溯古籍书目。","frontmatter":{"title":"易经：专题导读与学习地图","description":"从阴阳、八卦和六爻读法进入六十四卦经文、十翼与历代注解，配合本地图谱、术语表和可追溯古籍书目。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"从阴阳、八卦和六爻读法进入六十四卦经文、十翼与历代注解，配合本地图谱、术语表和可追溯古籍书目。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history"}},"headers":[],"relativePath":"life/personal/yijing/overview.md","filePath":"life/personal/yijing/overview.md"}'),h={name:"life/personal/yijing/overview.md"};function s(g,t,f,p,c,m){const e=d("ArticleImage");return i(),n("div",null,[t[0]||(t[0]=a('<h1 id="易经-专题导读与学习地图" tabindex="-1">易经：专题导读与学习地图 <a class="header-anchor" href="#易经-专题导读与学习地图" aria-label="Permalink to &quot;易经：专题导读与学习地图&quot;">​</a></h1><p>《易经》值得慢读：它既保存了古代占筮语言和生活经验，又在漫长的解释过程中形成了关于变化、处境、行动和责任的思想资源。本专题把入门知识、六十四卦经文、传文、注释传统与图象放在同一条阅读路径上。每一卦都可以从索引直接定位，不必先背完六十四卦。</p><p>这里的“易经”采用日常的广义用法；具体讨论时区分《周易》的 <strong>经文</strong> 、解释经文的 <strong>《易传》</strong> 和更晚的 <strong>易学</strong> 。本专题是一套有来源的综合入门与进阶资料，不能替代历代全部易学著述，也不是校勘定本。</p><h2 id="先建立四层认识" tabindex="-1">先建立四层认识 <a class="header-anchor" href="#先建立四层认识" aria-label="Permalink to &quot;先建立四层认识&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>主要材料</th><th>阅读时的问题</th></tr></thead><tbody><tr><td>经文</td><td>六十四卦的卦名、卦辞、爻辞，乾坤的用九与用六</td><td>原句说了什么？涉及什么形象、动作、条件和判断？</td></tr><tr><td>传文</td><td>彖、象、文言、系辞、说卦、序卦、杂卦</td><td>传文怎样把占筮语句解释为德行、时位和天地变化？</td></tr><tr><td>历代注解</td><td>王弼、韩康伯、孔颖达、程颐、朱熹等</td><td>各家关注的重点、文字训诂和推理方式有何不同？</td></tr><tr><td>后世发展与今人运用</td><td>图书之学、纳甲与其他术数、现代阅读练习</td><td>哪些是后起体系？哪些只是今天借古文作出的类比？</td></tr></tbody></table><p>这种分层来自作品本身的结构及注本的差异。参看<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93" target="_blank" rel="noopener noreferrer">《周易》经传目录</a>、<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《易传》目录</a>与<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》四库本提要及正文</a>。网页的传统作者标签也需要与<a href="./text-history">成书和版本问题</a>分开看。</p><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><h3 id="第一次读" tabindex="-1">第一次读 <a class="header-anchor" href="#第一次读" aria-label="Permalink to &quot;第一次读&quot;">​</a></h3><ol><li>阅读<a href="./symbols">阴阳、卦画与六爻</a>，能说清阴爻、阳爻、上卦、下卦。</li><li>看<a href="./trigrams">八卦取象</a>，先记天、地、雷、风、水、火、山、泽。</li><li>按<a href="./hexagram-reading">一卦的阅读步骤</a>，练习把经文与《彖》《象》分开。</li><li>对照<a href="./hexagrams-01-08#gua-01">乾、坤</a>、<a href="./hexagrams-09-16#gua-11">泰、否</a>、<a href="./hexagrams-57-64#gua-63">既济、未济</a>，体会相反处境为什么不能用同一句话解释。</li><li>再读<a href="./ten-wings">十翼导读</a>，理解古人如何解释经文。</li></ol><p>这条顺序是本站的学习建议，不是古代的唯一课程。每天读一卦也可以；重点是留出查字、对照和重读的时间。</p><h3 id="已经认识卦画" tabindex="-1">已经认识卦画 <a class="header-anchor" href="#已经认识卦画" aria-label="Permalink to &quot;已经认识卦画&quot;">​</a></h3><p>从<a href="./hexagram-index">六十四卦索引</a>查找具体卦，随后读<a href="./commentaries">历代注家比较</a>、<a href="./philosophy">易学思想</a>和<a href="./diagrams">图书之学</a>。某句话存在分歧时，记下“原字、断句、注家、解释理由”，不要直接拼成一个看似一致的答案。</p><h3 id="主要关心传统筮法" tabindex="-1">主要关心传统筮法 <a class="header-anchor" href="#主要关心传统筮法" aria-label="Permalink to &quot;主要关心传统筮法&quot;">​</a></h3><p>先读<a href="./divination">筮法及其解释边界</a>，再读<a href="./traditions">后世易学与术数分界</a>。起卦方法、变爻取用规则和解释体系必须分别说明；不同方法并不天然等价。学习其文化史可以很具体，但得到一个卦并不构成现实结果会发生的证据。</p><h2 id="专题目录" tabindex="-1">专题目录 <a class="header-anchor" href="#专题目录" aria-label="Permalink to &quot;专题目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>文章</th><th>可以解决的问题</th></tr></thead><tbody><tr><td>入门</td><td><a href="./text-history">经传、成书与版本</a></td><td>为什么不能把伏羲、文王、周公、孔子的传统归属都当作已证实的写作史？</td></tr><tr><td>入门</td><td><a href="./symbols">阴阳、卦画与六爻</a></td><td>爻从哪一端读？为什么是八卦、六十四卦、三百八十四爻？</td></tr><tr><td>入门</td><td><a href="./trigrams">八卦名称、性质与取象</a></td><td>乾健、坤顺等词是什么意思？取象表如何使用？</td></tr><tr><td>读法</td><td><a href="./hexagram-reading">一卦的阅读步骤</a></td><td>卦辞、爻辞、彖、大象、小象怎样关联？</td></tr><tr><td>查阅</td><td><a href="./hexagram-index">六十四卦索引与上下卦查表</a></td><td>由卦名、卦序或上下卦找到正文。</td></tr><tr><td>经文</td><td><a href="./hexagrams-01-08">01—08：乾、坤、屯、蒙、需、讼、师、比</a></td><td>从开端、成长到等待、争讼与群体。</td></tr><tr><td>经文</td><td><a href="./hexagrams-09-16">09—16：小畜、履、泰、否、同人、大有、谦、豫</a></td><td>积蓄、交往、通塞与拥有之后的节制。</td></tr><tr><td>经文</td><td><a href="./hexagrams-17-24">17—24：随、蛊、临、观、噬嗑、贲、剥、复</a></td><td>跟随、整治、观察、文饰与消长。</td></tr><tr><td>经文</td><td><a href="./hexagrams-25-32">25—32：无妄、大畜、颐、大过、坎、离、咸、恒</a></td><td>真实、养护、过重、险明与感应持久。</td></tr><tr><td>经文</td><td><a href="./hexagrams-33-40">33—40：遯、大壮、晋、明夷、家人、睽、蹇、解</a></td><td>退进、明暗、家庭、差异与解困。</td></tr><tr><td>经文</td><td><a href="./hexagrams-41-48">41—48：损、益、夬、姤、萃、升、困、井</a></td><td>损益、决断、相遇、聚集及公共滋养。</td></tr><tr><td>经文</td><td><a href="./hexagrams-49-56">49—56：革、鼎、震、艮、渐、归妹、丰、旅</a></td><td>变革、承载、惊动、止息与渐进。</td></tr><tr><td>经文</td><td><a href="./hexagrams-57-64">57—64：巽、兑、涣、节、中孚、小过、既济、未济</a></td><td>进入、交流、离散、节度与未完之事。</td></tr><tr><td>经传</td><td><a href="./ten-wings">十翼逐篇导读</a></td><td>七种十篇各自解释什么？</td></tr><tr><td>注释</td><td><a href="./commentaries">注家与读法比较</a></td><td>义理、象数与占筮视角怎样形成不同结论？</td></tr><tr><td>思想</td><td><a href="./philosophy">变化、时位与伦理</a></td><td>“中正”“变通”“生生”如何落在原文中？</td></tr><tr><td>图象</td><td><a href="./diagrams">先后天、河洛与历史图谱</a></td><td>图的方位、年代和传统命名是什么？</td></tr><tr><td>筮法</td><td><a href="./divination">大衍、钱币与变爻</a></td><td>怎样复原操作？哪些步骤属于后世解释？</td></tr><tr><td>流变</td><td><a href="./traditions">后世易学与术数分界</a></td><td>纳甲、梅花、风水、医易与《周易》是什么关系？</td></tr><tr><td>实践</td><td><a href="./reading-practice">对读与生活阅读练习</a></td><td>如何作有文本依据的反思，而不把类比当预测？</td></tr><tr><td>速查</td><td><a href="./glossary">术语、读音与常见误解</a></td><td>查爻位、异体字、吉凶用语和常见误读。</td></tr><tr><td>来源</td><td><a href="./bibliography">古籍、图片与整理说明</a></td><td>核对原书、图片出处与本专题的整理范围。</td></tr></tbody></table><h2 id="图谱入口" tabindex="-1">图谱入口 <a class="header-anchor" href="#图谱入口" aria-label="Permalink to &quot;图谱入口&quot;">​</a></h2>',17)),o("p",null,[l(e,{src:"/life/yijing/hexagrams.svg",alt:"六十四卦通行卦序图，初爻从下方起数"})]),t[1]||(t[1]=a('<p>本图为本站依据通行卦序绘制的学习图，详细出处与历史原图见<a href="./diagrams">图谱说明</a>。上经有三十卦，下经有三十四卦；本专题每八卦一篇只是为了浏览方便，第 25—32 卦一篇跨越上下经分界。</p><h2 id="怎样使用逐卦正文" tabindex="-1">怎样使用逐卦正文 <a class="header-anchor" href="#怎样使用逐卦正文" aria-label="Permalink to &quot;怎样使用逐卦正文&quot;">​</a></h2><p>先读卦辞和爻辞，不急着把现实事件套进去；然后观察同一卦内，六爻的处境和判断是否相同。最后再看《象》与解释。卦辞的整体判断不会取消爻辞的具体条件，例如<a href="./hexagrams-09-16#gua-11">泰卦</a>开篇“吉亨”，末爻仍然写到“城复于隍”；<a href="./hexagrams-57-64#gua-63">既济</a>也同时有“初吉”与“终乱”。</p><p>逐卦页中的“概括”“读法”“误区”和练习是本站整理；引号、引用块或明确标成“原文”的部分才是古籍文字。简体讲解与繁体原文并列，保留“无”“貞”等常见古籍字形；具体异文以相应页面说明为准。</p><h2 id="阅读时保留三个问题" tabindex="-1">阅读时保留三个问题 <a class="header-anchor" href="#阅读时保留三个问题" aria-label="Permalink to &quot;阅读时保留三个问题&quot;">​</a></h2><ul><li><strong>这是谁说的？</strong> 经文、传文、哪一位注家，还是本站作者？</li><li><strong>根据是什么？</strong> 文字训诂、上下卦形、爻位关系、历史背景，还是现代联想？</li><li><strong>结论到哪里为止？</strong> 文本说明一种处境，不等于已经确定你未来的职业、疾病、关系或收益。</li></ul><p>能够把这三个问题说清楚，比记住一个“吉卦榜”更有用。下一步可从<a href="./symbols">卦画入门</a>开始。</p>',7))])}const b=r(h,[["render",s]]);export{x as __pageData,b as default};
